assert len(rgb) == W * H * 3, "Expected exactly W * H * 3 channel values"

# Output: columns left to right; within each column, bottom LED to top LED.
out = []
for x in range(W):
    for led in range(H):
        y = H - 1 - led  # Reverse rows: LED 0 is at the bottom.
        i = (y * W + x) * 3
        r, g, b = rgb[i:i + 3]
        out.extend((b, g, r))       # BRG buffer order
        
print(f"const uint8_t columns[{W}][{H * 3}] PROGMEM = {{")
for x in range(W):
    start = x * H * 3
    values = ", ".join(str(v) for v in out[start:start + H * 3])
    print(f"  {{{values}}},")
print("};")